import {indicators,numberLabel,periodLabel,rangeRows} from './observatorio-economy-data.mjs';
export function initEconomy({db,esc,login,search}){
 const root=document.getElementById('economia'),data={},errors={},loading=new Set();let selected='dolar',months=12,tab='all',uid=null,favorites=new Set(),epoch=0,ready=false,busy=false,message='',started=false;
 const link=(url,label)=>`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)} ↗</a>`;
 function chart(rows,id,small=false){if(!rows.length)return '<p>No hay observaciones en este período.</p>';const w=720,h=280,left=65,right=15,top=20,bottom=40,values=rows.map(r=>r.value),lo=Math.min(...values),hi=Math.max(...values),pad=(hi-lo)*.1||Math.max(Math.abs(lo)*.02,.1),min=lo-pad,max=hi+pad,t0=Date.parse(rows[0].date),t1=Date.parse(rows.at(-1).date),x=r=>left+(Date.parse(r.date)-t0)/(t1-t0||1)*(w-left-right),y=r=>top+(max-r.value)/(max-min)*(h-top-bottom);let path='';rows.forEach((r,i)=>{const px=x(r),py=y(r);path+=i?(id==='tpm'?` H${px} V${py}`:` L${px},${py}`):`M${px},${py}`;});
 return `<svg class="${small?'econ-spark':'econ-chart'}" viewBox="0 0 ${w} ${h}" ${small?'aria-hidden="true"':`role="img" aria-label="${esc(indicators[id].name)}: ${esc(periodLabel(rows[0].date))} a ${esc(periodLabel(rows.at(-1).date))}. ${rows.length} observaciones. Valores exactos en la tabla."`}>${small?'':Array.from({length:4},(_,i)=>{const v=min+(max-min)*i/3,yy=y({value:v});return `<line x1="${left}" x2="${w-right}" y1="${yy}" y2="${yy}" stroke="#dde6e1"/><text x="${left-8}" y="${yy+4}" text-anchor="end">${esc(new Intl.NumberFormat('es-CL',{maximumFractionDigits:2}).format(v))}</text>`;}).join('')}<path d="${path}" fill="none" stroke="#167766" stroke-width="${small?7:2.5}"/>${small?'':`${rows.length===1?`<circle cx="${x(rows[0])}" cy="${y(rows[0])}" r="4" fill="#167766"/>`:''}<text x="${left}" y="${h-10}">${esc(rows[0].date)}</text><text x="${w-right}" y="${h-10}" text-anchor="end">${esc(rows.at(-1).date)}</text>`}</svg>`;}
 function render(){const d=data[selected],meta=indicators[selected],rows=d?rangeRows(d.series,months,d.date.length===7?d.date+'-01':d.date,selected==='tpm'):[],ids=Object.keys(indicators).filter(id=>tab!=='favorites'||favorites.has(id));
 root.innerHTML=`<div class="heading econ-heading"><div><span class="eyebrow">HERRAMIENTAS / ECONOMÍA</span><h1>Pulso económico</h1><p>Entiende los números que mueven tu día.</p></div><span class="badge">Chile · fuentes públicas</span></div>
 <div class="econ-toolbar"><div role="group" aria-label="Vista económica"><button data-econ-tab="all" aria-pressed="${tab==='all'}">Resumen</button><button data-econ-tab="favorites" aria-pressed="${tab==='favorites'}">★ Mis indicadores</button><button data-econ-tab="compare" aria-pressed="${tab==='compare'}">Comparar</button></div><button id="econ-refresh">↻ Actualizar datos</button></div>
 <section class="econ-overview"><strong>En un vistazo</strong><p>Monedas, precios y actividad. Cada indicador tiene su propio período: una fecha de consulta reciente no cambia la fecha del dato.</p></section>
 <p role="status" class="muted" id="econ-account-status">${esc(message||(!uid?'Ingresa con Convergencia para sincronizar favoritos entre tus dispositivos.':ready?'Favoritos privados, guardados en tu cuenta.':'Cargando favoritos…'))} ${!uid?'<button id="econ-login">Ingresar</button>':''}</p>
 <div class="econ-cards">${ids.map(id=>{const r=data[id],m=indicators[id];return `<article class="econ-card ${selected===id?'selected':''}"><div class="econ-card-top"><button class="econ-pick" data-econ-select="${id}" aria-pressed="${selected===id}">${esc(m.name)}</button><button class="econ-star" data-econ-star="${id}" aria-label="${favorites.has(id)?'Quitar':'Guardar'} ${esc(m.name)} de favoritos" aria-pressed="${favorites.has(id)}" ${busy||(uid&&!ready)?'disabled':''}>${favorites.has(id)?'★':'☆'}</button></div><button class="econ-value" data-econ-select="${id}" aria-label="Ver histórico de ${esc(m.name)}">${r?numberLabel(r.value,id):loading.has(id)?'Cargando…':'Sin conexión'}</button><small>${esc(m.unit)}</small>${r?`${chart(r.series.slice(-30),id,true)}<small>Dato: ${esc(periodLabel(r.date))}</small><small>${esc(r.source.name)}</small>${r.annual!==null?`<small>12 meses: ${numberLabel(r.annual,'ipc')}</small>`:''}${r.stale||r.delayed?'<span class="econ-warning">Último dato conservado · revisa la fecha</span>':''}`:`<p>${errors[id]?'No se pudo consultar. Reintenta con Actualizar datos.':'Consultando la fuente…'}</p>`}</article>`;}).join('')||`<div class="panel">${uid?'Todavía no guardas indicadores. Usa ☆ en Resumen.':'Ingresa para ver tus indicadores guardados.'}</div>`}</div>
 ${tab==='compare'?`<section class="panel"><h2>Comparar el período · ${months} meses</h2><p>Primer y último dato disponibles dentro de la ventana de cada serie. Las diferencias en tasas se expresan en puntos porcentuales, no en variación porcentual.</p><div class="econ-table"><table><thead><tr><th>Indicador</th><th>Inicio disponible</th><th>Último dato</th><th>Diferencia</th></tr></thead><tbody>${Object.keys(indicators).map(id=>{const item=data[id],r=item?rangeRows(item.series,months,item.date.length===7?item.date+'-01':item.date,id==='tpm'):[],a=r[0],b=r.at(-1);return `<tr><td>${esc(indicators[id].name)}</td><td>${a?numberLabel(a.value,id)+'<br><small>'+esc(periodLabel(a.date))+'</small>':'Sin dato'}</td><td>${b?numberLabel(b.value,id)+'<br><small>'+esc(periodLabel(b.date))+'</small>':'Sin dato'}</td><td>${a&&b?esc(new Intl.NumberFormat('es-CL',{maximumFractionDigits:2,signDisplay:'always'}).format(b.value-a.value))+' '+(indicators[id].symbol==='%'?'pp':esc(indicators[id].unit)):'—'}</td></tr>`;}).join('')}</tbody></table></div></section>`:''}<div class="econ-detail"><section class="panel econ-history"><div class="econ-chart-heading"><div><h2>${esc(meta.name)}</h2><p>${esc(meta.unit)}</p></div><div role="group" aria-label="Período histórico">${[[1,'1M'],[6,'6M'],[12,'1A'],[60,'5A']].map(([n,label])=>`<button data-econ-months="${n}" aria-pressed="${months===n}">${label}</button>`).join('')}</div></div>${d?`${chart(rows,selected)}<p class="muted">Cobertura disponible: ${esc(periodLabel(d.series[0].date))} – ${esc(periodLabel(d.date))}. ${rows.filter(r=>!r.carried).length} observaciones publicadas en la selección.${selected==='tpm'?' Línea escalonada: tasa mantenida entre decisiones.':''}</p>${d.effectiveSince?`<p>Vigente desde ${esc(periodLabel(d.effectiveSince))}.</p>`:''}<details><summary>Ver valores exactos y fechas</summary><div class="econ-table"><table><thead><tr><th>Fecha</th><th>${esc(meta.unit)}</th></tr></thead><tbody>${rows.filter(r=>!r.carried).slice().reverse().map(r=>`<tr><td>${esc(periodLabel(r.date))}</td><td>${numberLabel(r.value,selected)}</td></tr>`).join('')||'<tr><td colspan="2">Sin nuevas decisiones en el período; se mantiene la tasa anterior.</td></tr>'}</tbody></table></div></details>`:'<p role="status">'+(loading.has(selected)?'Cargando histórico…':'Histórico no disponible. Reintenta con Actualizar datos.')+'</p>'}</section>
 <aside class="panel econ-context"><span class="eyebrow">CONTEXTO</span><h2>Qué significa</h2><p>${esc(meta.explanation)}</p>${d?`<h3>Fecha y procedencia</h3><p>Dato: <strong>${esc(periodLabel(d.date))}</strong></p><p>${link(d.source.url,d.source.name)}</p><p>Distribuido por ${link(d.providerUrl,d.provider)}. Proveedor independiente de las instituciones oficiales.</p><small>Consulta de Atlas: ${esc(new Date(d.retrievedAt).toLocaleString('es-CL'))}</small>${d.providerUpdatedAt?`<small>Actualización del proveedor: ${esc(new Date(d.providerUpdatedAt).toLocaleString('es-CL'))}</small>`:''}${d.stale?'<p class="econ-warning">La última actualización falló. Conservamos la consulta anterior.</p>':''}`:''}<button id="econ-news">Noticias sobre ${esc(meta.name)} ↗</button></aside></div>
 <p class="muted econ-credit">Datos: ${link('https://indicadores.cl/api/','indicadores.cl')}. Series diarias o mensuales, no cotizaciones en tiempo real. Las revisiones del proveedor reemplazan la serie anterior. El IPC del gráfico es mensual, no anual.</p>`;
 root.querySelectorAll('[data-econ-select]').forEach(b=>b.onclick=()=>{selected=b.dataset.econSelect;render();});root.querySelectorAll('[data-econ-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.econTab;render();});root.querySelectorAll('[data-econ-months]').forEach(b=>b.onclick=()=>{months=Number(b.dataset.econMonths);render();});root.querySelectorAll('[data-econ-star]').forEach(b=>b.onclick=()=>toggle(b.dataset.econStar));root.querySelector('#econ-login')?.addEventListener('click',login);root.querySelector('#econ-news').onclick=()=>search(meta.name+' Chile');root.querySelector('#econ-refresh').onclick=load;
 }
 async function load(){started=true;await Promise.allSettled(Object.keys(indicators).map(async id=>{if(loading.has(id))return;loading.add(id);render();try{const r=await fetch('/.netlify/functions/economy?indicator='+id,{signal:AbortSignal.timeout(40000)});if(!r.ok)throw Error();const value=await r.json();if(value.id!==id||!Array.isArray(value.series))throw Error();data[id]=value;errors[id]=false;}catch{errors[id]=true;if(data[id])data[id]={...data[id],stale:true};}finally{loading.delete(id);render();}}));}
 async function sync(){if(!uid||busy)return;const token=epoch,owner=uid;try{const {data:rows,error}=await db.from('atlas_dev_economic_favorites').select('indicator').eq('user_id',owner);if(token!==epoch)return;if(error)throw error;favorites=new Set((rows||[]).map(r=>r.indicator));ready=true;message='';}catch{if(token===epoch){ready=false;message='No se pudieron cargar los favoritos. Vuelve a entrar a Pulso económico para reintentar.';}}if(token===epoch)render();}
 async function toggle(id){if(!uid){login();return;}if(busy||!ready)return;const token=++epoch,owner=uid,remove=favorites.has(id);busy=true;message='Guardando…';render();try{const q=db.from('atlas_dev_economic_favorites');const {error}=remove?await q.delete().eq('user_id',owner).eq('indicator',id):await q.insert({user_id:owner,indicator:id});if(token!==epoch)return;if(error&&error.code!=='23505')throw error;remove?favorites.delete(id):favorites.add(id);message='Guardado en tu cuenta de Convergencia.';}catch{if(token===epoch)message='No se pudo guardar. Inténtalo de nuevo.';}finally{if(token===epoch){busy=false;render();}}}
 async function session(user){const next=user?.id||null;if(next===uid)return;epoch++;uid=next;favorites=new Set();ready=false;busy=false;message='';render();if(uid)await sync();}
 if(db){db.auth.getSession().then(({data})=>session(data?.session?.user));db.auth.onAuthStateChange((_,s)=>setTimeout(()=>session(s?.user),0));}
 document.addEventListener('visibilitychange',()=>{if(!document.hidden&&!root.hidden)sync();});render();return {open(){if(!started)load();sync();}};
}
